package calc

import "testing"

func TestSum(t *testing.T) {
	if got := Sum([]int{1, 2, 3}); got != 6 {
		t.Fatalf("Sum = %d, want 6", got)
	}
}

func TestMean(t *testing.T) {
	got, ok := Mean([]int{1, 2, 3, 4})
	if !ok || got != 2.5 {
		t.Fatalf("Mean = %v, %v, want 2.5, true", got, ok)
	}
}

