func TestMax(t *testing.T) {
	tests := []struct {
		name string
		xs   []int
		want int
		ok   bool
	}{
		{"empty slice", []int{}, 0, false},
		{"single element", []int{5}, 5, true},
		{"multiple elements", []int{1, 2, 3, 4, 5}, 5, true},
		{"max at start", []int{10, 1, 2, 3}, 10, true},
		{"max at end", []int{1, 2, 3, 10}, 10, true},
		{"max in middle", []int{1, 10, 2, 3}, 10, true},
		{"negative numbers", []int{-5, -2, -10, -1}, -1, true},
		{"mixed positive and negative", []int{-5, 10, -2, 3}, 10, true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, ok := Max(tt.xs)
			if got != tt.want || ok != tt.ok {
				t.Errorf("Max(%v) = %d, %v, want %d, %v", tt.xs, got, ok, tt.want, tt.ok)
			}
		})
	}
}

