// Package calc holds small numeric helpers.
package calc

// Sum adds xs.
func Sum(xs []int) int {
	total := 0
	for _, x := range xs {
		total += x
	}
	return total
}

// Mean is the average of xs, and false when xs is empty.
func Mean(xs []int) (float64, bool) {
	if len(xs) == 0 {
		return 0, false
	}
	return float64(Sum(xs)) / float64(len(xs)), true
}

// Max returns the largest value in xs, and false when xs is empty.
func Max(xs []int) (int, bool) {
	if len(xs) == 0 {
		return 0, false
	}
	max := xs[0]
	for _, x := range xs[1:] {
		if x > max {
			max = x
		}
	}
	return max, true
}
